import random

def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    rng = random.Random(sum((i + 1) * v for i, v in enumerate(vals)))
    out = [[grid[r % h][c % w] for c in range(2*w)] for r in range(2*h)]
    for r in range(2*h):
        for c in range(2*w):
            if r >= h or c >= w:
                out[r][c] = rng.choice(vals)
    return out
